<script setup>
import {ref,computed,onMounted,onUnmounted,nextTick} from 'vue';
import {createExerciseClock,breathingAt,groundingSteps,breathingRecordTime} from './controllers/exerciseClock.js';import {api} from './lib/api.js';import {createSessionPersistence} from './controllers/sessionPersistence.js';
import ChatPanel from './components/ChatPanel.vue';
import BreathingExercise from './components/BreathingExercise.vue';import GroundingExercise from './components/GroundingExercise.vue';import SupportPanel from './components/SupportPanel.vue';import HistoryPanel from './components/HistoryPanel.vue';
const view=ref('home'),support=ref(false),simple=ref(false),reduced=ref(false),color=ref('red'),recent=ref(null),state=ref('ready'),elapsed=ref(0),step=ref(0),skipped=ref([]),preferenceError=ref(''),busy=ref(false),saveRevision=ref(0),currentRecord=ref(null),conversationId=ref(null),chatKey=ref(0),clearingHistory=ref(false),timing=ref({entry:null,firstFrame:null,finalFrame:null});
let clock=null,frame=null,lastPersist=0;
const persistence=createSessionPersistence(api,()=>saveRevision.value++);const saved=computed(()=>{saveRevision.value;return currentRecord.value?.saved;});const unsaved=computed(()=>{saveRevision.value;return persistence.pending;});
const breathing=computed(()=>breathingAt(elapsed.value));const skill=ref(null);
function tick(){if(clock){const snap=clock.snapshot();elapsed.value=snap.elapsedMs;if(state.value==='active' && elapsed.value-lastPersist>=5000){lastPersist=elapsed.value;persist();}if(skill.value==='breathing' && state.value==='active' && elapsed.value>=60000){clock.finish();elapsed.value=60000;state.value='completed';markFrame(true);persist();}}frame=requestAnimationFrame(tick);}
function sessionBody(){const duration=skill.value==='breathing'?breathingRecordTime(elapsed.value):{active_elapsed_ms:Math.floor(elapsed.value),cycles:0};return {state:state.value,...duration,step:step.value,skipped_steps:[...skipped.value]};}
function persist(){if(currentRecord.value)persistence.update(currentRecord.value,sessionBody());}
function markFrame(final=false){const target=timing.value;nextTick(()=>requestAnimationFrame(()=>requestAnimationFrame(timestamp=>{if(timing.value!==target)return;if(final)target.finalFrame=timestamp;else target.firstFrame=timestamp;})));}
function start(which){if(clearingHistory.value||busy.value||['active','paused'].includes(state.value)&&view.value===which)return; if(['active','paused'].includes(state.value))navigate('home');timing.value={entry:performance.now(),firstFrame:null,finalFrame:null};skill.value=which;lastPersist=0;step.value=0;skipped.value=[];elapsed.value=0;state.value='active';clock=createExerciseClock();clock.start();view.value=which;currentRecord.value=persistence.create({request_id:crypto.randomUUID(),skill:which,conversation_id:conversationId.value});markFrame();}
async function retrySave(){busy.value=true;await persistence.retryAll();busy.value=false;}
function pause(){if(state.value!=='active')return;clock.pause();elapsed.value=clock.snapshot().elapsedMs;state.value='paused';persist();}
function resume(){if(state.value!=='paused')return;clock.resume();state.value='active';persist();}
function stop(){if(!['active','paused'].includes(state.value))return;clock.finish('stopped');elapsed.value=clock.snapshot().elapsedMs;state.value='stopped';persist();}
function navigate(where){if(clearingHistory.value)return;if(['active','paused'].includes(state.value)){clock.finish('interrupted');elapsed.value=clock.snapshot().elapsedMs;state.value='interrupted';persist();}view.value=where;loadRecent();}
function next(skip=false){if(state.value!=='active')return;if(skip)skipped.value.push(step.value);step.value++;elapsed.value=clock.snapshot().elapsedMs;if(step.value===5){clock.finish();state.value='completed';markFrame(true);}persist();}
async function preferences(){try{const p=await api('/preferences');color.value=p.explicit_balloon_color||'red';simple.value=p.simple_view;reduced.value=p.reduced_motion||matchMedia('(prefers-reduced-motion: reduce)').matches;}catch{reduced.value=matchMedia('(prefers-reduced-motion: reduce)').matches;}}
async function preference(key,value){try{await api('/preferences',{method:'PATCH',body:{[key]:value}});preferenceError.value='';}catch{preferenceError.value='Preference changed for this visit, but could not be saved.';}}
async function resetPreferences(){try{await api('/preferences',{method:'DELETE'});await preferences();preferenceError.value='';}catch{preferenceError.value='Preferences could not be reset. Try again.';}}
async function loadRecent(){try{const s=await api('/sessions');recent.value=s.items[0]?.skill||null;}catch{recent.value=null;}}
async function beforeClearHistory(){clearingHistory.value=true;await persistence.discardAll();conversationId.value=null;chatKey.value++;currentRecord.value=null;}
function visibility(){if(document.hidden)pause();}
function openSupport(){pause();support.value=true;}
onMounted(()=>{preferences();loadRecent();frame=requestAnimationFrame(tick);document.addEventListener('visibilitychange',visibility);});onUnmounted(()=>{cancelAnimationFrame(frame);document.removeEventListener('visibilitychange',visibility);});
</script>
<template><div class="app-shell" :class="{simple}"><header class="site-header"><button :disabled="clearingHistory" class="brand" @click="navigate('home')"><span class="brand-mark" aria-hidden="true">✳</span><span>campus pause</span></button><nav aria-label="Main"><button :disabled="clearingHistory" class="text-button" @click="navigate('home')">Home</button><button :disabled="clearingHistory" v-if="!simple" class="text-button" @click="navigate('history')">History</button><button class="text-button" :aria-pressed="simple" @click="simple=!simple;preference('simple_view',simple)">{{simple?'Full view':'Simpler view'}}</button></nav></header><main><div v-show="view==='home'" class="home-layout"><section class="intro"><span class="eyebrow">A little room to pause</span><h1>One moment.<br><em>Your own pace.</em></h1><p class="lead">Want a brief pause? You can chat, or choose an exercise. No need to explain.</p><ChatPanel :key="chatKey" v-show="!simple" :active="view==='home'&&!simple" @choose="start" @conversation="conversationId=$event" @support="openSupport"/><div v-if="recent" class="recent"><span class="fine">Your most recent pause</span><button class="text-button" @click="start(recent)">Repeat {{recent==='breathing'?'breathing':'grounding'}} →</button></div></section><section class="choices" aria-label="Begin an exercise"><button class="skill-card" :disabled="clearingHistory" @click="start('breathing')"><span class="skill-symbol breath-symbol" aria-hidden="true">◌</span><span class="eyebrow">01 / A steady rhythm</span><h2>Paced breathing</h2><p>Follow a gentle four-in, six-out rhythm.</p><span class="skill-footer">60 seconds <span aria-hidden="true">↗</span></span></button><button class="skill-card" :disabled="clearingHistory" @click="start('grounding')"><span class="skill-symbol" aria-hidden="true">✳</span><span class="eyebrow">02 / Here and now</span><h2>Sensory grounding</h2><p>Notice the world around you, one sense at a time.</p><span class="skill-footer">About a minute <span aria-hidden="true">↗</span></span></button><div class="settings" v-if="!simple"><label>Balloon color <select v-model="color" @change="preference('explicit_balloon_color',color)"><option value="red">Red</option><option value="sage">Sage</option><option value="blue">Blue</option><option value="plum">Plum</option></select></label><label class="check-label"><input type="checkbox" v-model="reduced" @change="preference('reduced_motion',reduced)"> Reduced motion</label><button class="text-button" @click="resetPreferences">Reset preferences</button></div></section></div><BreathingExercise v-if="view==='breathing'" :snapshot="breathing" :timing="timing" :state="state" :color="color" :reduced="reduced" @pause="pause" @resume="resume" @stop="stop" @home="navigate('home')"/><GroundingExercise v-if="view==='grounding'" :timing="timing" :elapsed="elapsed" :step="groundingSteps[Math.min(step,4)]" :index="step" :state="state" :skipped="skipped" @next="next()" @skip="next(true)" @pause="pause" @resume="resume" @stop="stop" @home="navigate('home')"/><HistoryPanel :before-clear="beforeClearHistory" :unsaved-count="unsaved.length" v-if="view==='history'" @repeat="start" @refresh="loadRecent" @clear-finished="clearingHistory=false"/><div v-if="preferenceError" class="save-status" role="status">{{preferenceError}}</div><div v-if="unsaved.length" class="save-status" role="status">{{unsaved.length}} exercise record(s) awaiting saved history. You can continue. <button class="text-button" :disabled="busy" @click="retrySave">Retry saving</button><p class="fine"><span v-for="record in unsaved" :key="record.start.request_id" class="unsaved-record">{{record.start.skill}} · {{record.operations.at(-1)?.state||record.saved?.state||'active'}} · {{record.error||'saving'}}</span>Unsaved records remain in this visit; closing or reloading can lose them.</p></div><p v-if="['breathing','grounding'].includes(view)&&saved&&!currentRecord?.operations.length&&!currentRecord?.error" class="saved-note fine">Saved locally · {{saved.state}}</p></main><footer class="site-footer"><p>Coursework prototype · fictional scenarios only · not monitored</p><button class="support-button" @click="openSupport"><span aria-hidden="true">♡</span> Support resources <span aria-hidden="true">↗</span></button></footer><SupportPanel v-if="support" @close="support=false"/></div></template>
